ALTER TABLE assets ADD COLUMN write_expires INTEGER NOT NULL DEFAULT 0;
DROP TRIGGER IF EXISTS protect_response_jobs_input_asset_insert;
CREATE TRIGGER protect_response_jobs_input_asset_insert BEFORE INSERT ON response_jobs WHEN NEW.input_asset IS NOT NULL AND NOT EXISTS(SELECT 1 FROM assets WHERE id=NEW.input_asset AND owner=NEW.owner AND storage_state='active') BEGIN SELECT RAISE(ABORT,'Referenced file is not available'); END;
